style.css:
/* Apply to the entire website (root level) */
html {
    /* Standard CSS properties (Supported in Firefox and modern Chrome/Safari/Edge) */
    /* Syntax: scrollbar-color: [thumb color] [track color] */
    scrollbar-color: rgba(255, 182, 193, 0.6) transparent;
    scrollbar-width: auto;
}

/* WebKit Engines (Chrome, Safari, Edge, Opera, and iOS browsers) */
/* 1. Define the width of the scrollbar */
::-webkit-scrollbar {
    width: 12px;
    height: 12px; /* For horizontal scrollbars */
}

/* 2. Style the background track (keep it transparent or matching) */
::-webkit-scrollbar-track {
    background: transparent;
}

/* 3. Style the movable thumb (light pink and translucent) */
::-webkit-scrollbar-thumb {
    background-color: rgba(255, 182, 193, 0.6); /* Light Pink with 60% opacity */
    border-radius: 10px;                         /* Rounded corners */
    border: 2px solid transparent;               /* Gives padding look inside the track */
    background-clip: padding-box;                /* Keeps the border invisible for padding */
}

/* 4. Darken the thumb slightly on hover for accessibility and feedback */
::-webkit-scrollbar-thumb:hover {
    background-color: rgba(255, 140, 155, 0.8); /* Darker pink with 80% opacity */
    border: 2px solid transparent;
    background-clip: padding-box;
}
